package net.hivel.islandsrpg.magic;
import net.hivel.islandsrpg.IslandsRPGPlugin; import net.hivel.islandsrpg.util.*; import net.hivel.islandsrpg.weapon.WeaponType; import org.bukkit.*; import org.bukkit.configuration.file.FileConfiguration; import org.bukkit.inventory.ItemStack; import org.bukkit.persistence.PersistentDataType; import java.util.*;
public class MagicItemService { private final IslandsRPGPlugin plugin; private final Map<String,MagicItemDefinition> items=new LinkedHashMap<>(); private final Map<UUID,Map<String,Long>> cooldowns=new HashMap<>(); public MagicItemService(IslandsRPGPlugin p){plugin=p;} public void reload(){FileConfiguration c=ConfigUtil.load(plugin,"magic-items.yml"); items.clear(); var sec=c.getConfigurationSection("magic-items"); if(sec==null)return; for(String id:sec.getKeys(false)){try{String p="magic-items."+id+"."; Material m=Material.matchMaterial(c.getString(p+"material","STICK")); if(m==null)continue; items.put(id,new MagicItemDefinition(id,m,WeaponType.valueOf(c.getString(p+"type","FIST")),c.getString(p+"display-name",id),c.getInt(p+"required-level",1),c.getDouble(p+"damage",1),c.getInt(p+"cooldown-seconds",0),c.getDouble(p+"magic-scaling",0),c.getBoolean(p+"glow",false),c.getStringList(p+"lore"),c.getBoolean(p+"particles.held.enabled",false),parseParticle(c.getString(p+"particles.held.particle","FLAME")),c.getInt(p+"particles.held.count",5),c.getInt(p+"particles.held.interval-ticks",10),c.getDouble(p+"particles.held.radius",.5),c.getBoolean(p+"particles.held.java-only",true),c.getBoolean(p+"particles.hit.enabled",false),parseParticle(c.getString(p+"particles.hit.particle","FLAME")),c.getInt(p+"particles.hit.count",8),c.getBoolean(p+"particles.hit.java-only",true),parseSound(c.getString(p+"sound.hit",null)),c.getString(p+"effect.type",""),c.getInt(p+"effect.duration-seconds",0),c.getInt(p+"effect.amplifier",0)));}catch(Exception e){plugin.getLogger().warning("Invalid magic item "+id);}}} private Particle parseParticle(String s){try{return Particle.valueOf(s);}catch(Exception e){return Particle.FLAME;}} private Sound parseSound(String s){try{return s==null?null:Sound.valueOf(s);}catch(Exception e){return null;}} public Collection<MagicItemDefinition> all(){return items.values();} public MagicItemDefinition get(String id){return items.get(id);} public ItemStack item(String id){var m=get(id); if(m==null)return null; return new ItemBuilder(m.material()).name(m.displayName()).lore(m.lore()).glow(m.glow()).unbreakable(true).pdc(plugin,"magic_id",id).build();} public MagicItemDefinition from(ItemStack item){if(item==null||!item.hasItemMeta())return null; String id=item.getItemMeta().getPersistentDataContainer().get(plugin.key("magic_id"), PersistentDataType.STRING); return id==null?null:get(id);} public long remaining(UUID player,String id){long until=cooldowns.getOrDefault(player,Map.of()).getOrDefault(id,0L); return Math.max(0, until-System.currentTimeMillis());} public void cooldown(UUID player,String id,int seconds){cooldowns.computeIfAbsent(player,k->new HashMap<>()).put(id,System.currentTimeMillis()+seconds*1000L);} }
